// BUILD DASHBOARD – one HTML page from the Job Tracker and the Run Log
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const jobs = $("Read Job Tracker").all().map((i) => i.json).filter((j) => j.job_id);
const runs = $("Read Run Log").all().map((i) => i.json).filter((r) => r.run_at)
  .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
const count = (f) => jobs.filter(f).length;
const FITS = ["Strong", "Possible", "Weak", "Red flag"];
const STATUSES = ["new", "applied", "interview", "offer", "rejected", "skipped"];
const byFit = FITS.map((f) => count((j) => j.fit === f));
const byStatus = STATUSES.map((s) => count((j) => (j.status || "new") === s));
const last = runs[runs.length - 1] || {};
const open = jobs.filter((j) => (j.fit === "Strong" || j.fit === "Possible") && (j.status || "new") === "new")
  .sort((a, b) => b.match_score - a.match_score).slice(0, 12);
const base = "http://localhost:5678/webhook/job-cv?job_id=";
const tiles = [
  ["Jobs tracked", jobs.length, ""],
  ["Strong matches", byFit[0], "fit = Strong"],
  ["Applied", count((j) => ["applied", "interview", "offer"].includes(j.status)), "applied, interview or offer"],
  ["Interviews", count((j) => ["interview", "offer"].includes(j.status)), ""],
  ["Last run", esc(last.status || "–"), esc(last.run_at || "no runs yet")]
];
const runLabels = runs.map((r) => String(r.run_at).slice(0, 10));
const data = {
  fits: FITS, byFit, statuses: STATUSES, byStatus, runLabels,
  newJobs: runs.map((r) => r.new_jobs || 0), scored: runs.map((r) => r.ai_scored || 0),
  tokens: runs.map((r) => r.ai_tokens || 0), seconds: runs.map((r) => r.duration_sec || 0)
};
const rows = open.map((j) => `<tr><td><a href="${esc(j.url)}" target="_blank" rel="noopener">${esc(j.title)}</a><div class="sub">${esc(j.company)} · ${esc(j.location)}${j.salary ? " · " + esc(j.salary) : ""}</div></td>
<td class="num">${esc(j.match_score)}</td><td><span class="pill ${esc(String(j.fit).replace(" ", "-").toLowerCase())}">${esc(j.fit)}</span></td>
<td class="flags">${esc(j.flags || "")}</td><td class="links">${j.tailored_cv ? `<a href="${base}${encodeURIComponent(j.job_id)}" target="_blank">CV page</a> · <a href="http://localhost:5678/webhook/tailored-cv?job_id=${encodeURIComponent(j.job_id)}">Word</a> · <a href="http://localhost:5678/webhook/tailored-cv?job_id=${encodeURIComponent(j.job_id)}&type=letter">Cover letter</a>` : "–"}</td></tr>`).join("");
const runRows = runs.slice(-8).reverse().map((r) => `<tr><td>${esc(r.run_at)}</td><td><span class="pill ${r.status === "OK" ? "ok" : r.status === "FAILED" ? "red-flag" : "possible"}">${esc(r.status)}</span></td>
<td class="num">${esc(r.jobs_found ?? "")}</td><td class="num">${esc(r.new_jobs ?? "")}</td><td class="num">${esc(r.ai_scored ?? "")}</td><td class="num">${esc(r.ai_failed ?? "")}</td><td class="num">${esc(Number(r.ai_tokens || 0).toLocaleString("en-GB"))}</td><td class="num">${esc(r.duration_sec ?? "")}s</td><td class="flags">${esc(r.notes || "")}</td></tr>`).join("");

const html = `<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Job Hunt Dashboard</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Sora:wght@500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js"></script>
<style>
:root{--bg:#060912;--ink:#e8f1ff;--muted:#93a4c3;--line:rgba(255,255,255,.09);--accent:#22d3ee;--c2:#818cf8;--c3:#f472b6;--strong:#34d399;--possible:#a78bfa;--weak:#64748b;--red:#fb7185;font-family:"Inter",system-ui,sans-serif}
html{background:var(--bg)}
body{margin:0;color:var(--ink);min-height:100vh;background:var(--bg);overflow-x:hidden}
