.rule{height:1px;margin:20px 0 12px;background:linear-gradient(90deg,rgba(34,211,238,.7),rgba(129,140,248,.5),rgba(244,114,182,.4),transparent)}
h2{font-family:"Sora",sans-serif;font-weight:600;font-size:16px;margin:0 0 14px;color:#e8f1ff;letter-spacing:-.01em}
h2::before{content:"";display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:10px;vertical-align:2px;background:linear-gradient(135deg,var(--accent),var(--c2));box-shadow:0 0 10px rgba(34,211,238,.8)}
.lead{color:var(--muted);margin:0 0 30px;font-size:13px}
.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin-bottom:16px}
.tile,.card{position:relative;background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.025));border:1px solid var(--line);border-radius:18px;padding:18px 20px;backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);box-shadow:0 10px 40px rgba(0,0,0,.35)}
.tile::before,.card::before{content:"";position:absolute;inset:0;border-radius:inherit;padding:1px;background:linear-gradient(135deg,rgba(34,211,238,.6),rgba(129,140,248,.25),rgba(244,114,182,.45));-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;pointer-events:none;opacity:.6}
.tile{transition:transform .25s ease,box-shadow .25s ease}.tile:hover{transform:translateY(-3px);box-shadow:0 16px 50px rgba(34,211,238,.18)}
.tile b{display:block;font-family:"Sora",sans-serif;font-size:36px;font-weight:700;margin:8px 0 2px;background:linear-gradient(135deg,#ffffff,#a5f3fc 60%,#c4b5fd);-webkit-background-clip:text;background-clip:text;color:transparent;font-variant-numeric:tabular-nums}
.tile span{font-family:"JetBrains Mono",monospace;color:var(--muted);font-size:10.5px;text-transform:uppercase;letter-spacing:.16em}
