.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;margin-bottom:16px}.card{min-width:0}
.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px}
