</style></head><body><main>
<p class="eyebrow">AI Job Hunt Agent · Private Dashboard</p><h1>Job Hunt <em>Dashboard</em></h1><div class="rule"></div><p class="lead">Updated ${esc(new Date().toLocaleString("en-GB", { timeZone: "Europe/London" }))} (UK time) · refresh the page for the latest data</p>
<div class="tiles">${tiles.map(([l, v, s]) => `<div class="tile"><span>${l}</span><b>${v}</b><small>${s}</small></div>`).join("")}</div>
<div class="grid"><div class="card"><h2>Jobs by fit</h2><canvas id="fit" height="200"></canvas></div>
<div class="card"><h2>Application pipeline</h2><canvas id="status" height="200"></canvas></div></div>
<div class="grid"><div class="card"><h2>Jobs per run</h2><canvas id="runs" height="200"></canvas></div>
<div class="card"><h2>AI tokens and run time</h2><canvas id="cost" height="200"></canvas></div></div>
<div class="card" style="margin-bottom:16px"><h2>Open matches to review (Strong / Possible, status new)</h2><div class="scroll"><table><thead><tr><th>Job</th><th>Score</th><th>Fit</th><th>Flags</th><th>Tailored CV</th></tr></thead><tbody>${rows || '<tr><td colspan="5">No open matches.</td></tr>'}</tbody></table></div></div>
<div class="card"><h2>Recent runs</h2><div class="scroll"><table><thead><tr><th>Run (UK)</th><th>Status</th><th>Found</th><th>New</th><th>Scored</th><th>Failed</th><th>Tokens</th><th>Time</th><th>Notes</th></tr></thead><tbody>${runRows || '<tr><td colspan="9">No runs yet.</td></tr>'}</tbody></table></div></div>
<footer>Scores are calculated in code from AI ratings that quote the CV; always review a job before applying.</footer>
</main><script>
const D=${JSON.stringify(data)};
if(window.Chart){const css=getComputedStyle(document.documentElement);const c=(v)=>css.getPropertyValue(v).trim();
Chart.defaults.color=c("--muted");Chart.defaults.borderColor=c("--line");Chart.defaults.font.family="Inter, Arial";
new Chart(document.getElementById("fit"),{type:"bar",data:{labels:D.fits,datasets:[{data:D.byFit,backgroundColor:[c("--strong"),c("--possible"),c("--weak"),c("--red")]}]},options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});
new Chart(document.getElementById("status"),{type:"bar",data:{labels:D.statuses,datasets:[{data:D.byStatus,backgroundColor:c("--accent")}]},options:{indexAxis:"y",plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,ticks:{precision:0}}}}});
new Chart(document.getElementById("runs"),{type:"line",data:{labels:D.runLabels,datasets:[{label:"New jobs",data:D.newJobs,borderColor:c("--accent"),tension:.3},{label:"AI scored",data:D.scored,borderColor:c("--strong"),tension:.3}]},options:{scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});
new Chart(document.getElementById("cost"),{type:"bar",data:{labels:D.runLabels,datasets:[{label:"AI tokens",data:D.tokens,backgroundColor:c("--accent"),yAxisID:"y"},{type:"line",label:"Run time (s)",data:D.seconds,borderColor:c("--possible"),yAxisID:"y1"}]},options:{scales:{y:{beginAtZero:true,position:"left"},y1:{beginAtZero:true,position:"right",grid:{drawOnChartArea:false}}}}});}
</script></body></html>`;
return [{ json: { html } }];

// BUILD TAILORED CV – full CV for one job, using the tailored summary, skills order and
// project bullets saved by the job agent. ?format=doc downloads it as a Word file.
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const q = $("Tailored CV Request").first().json.query || {};
const job = $input.all().map((i) => i.json).find((j) => j.job_id) || null;

const ME = {
  name: "Your Name",
  headline: "MSc Artificial Intelligence Student  ·  LLMs & Agentic AI  ·  Python  ·  AI Automation",
  contact: ["Your City, UK", "+44 0000 000000", "you@example.com", "linkedin.com/in/your-profile", "github.com/your-username"],
  summary: "Computer Science graduate and MSc Artificial Intelligence student at Teesside University who builds practical, explainable LLM applications. Built an AI CV screening assistant and an AI job-hunt agent in n8n that verify every AI evidence quote and calculate scores in code. Strong foundation in Python, machine learning, deep learning, REST APIs and responsible AI.",
  skills: [
    ["Languages", "Python, SQL, JavaScript, Java, C, C++"],
    ["LLMs & Agentic AI", "Large Language Models (LLMs), Generative AI, AI Agents (tools + memory), LangChain, LangGraph, Groq API, Prompt Engineering, Context Engineering, Structured Outputs (JSON Schema), LLM Output Verification"],
    ["Automation & APIs", "n8n (Webhooks, Schedule Trigger, HTTP Request, Code nodes, Data Tables, sub-workflows), REST APIs, API integration, JSON, Flask, Node.js, Express.js"],
    ["Machine Learning", "Deep Learning, Neural Networks, CNNs, Computer Vision, Model Training and Evaluation, TensorFlow, PyTorch, Scikit-learn, OpenCV, YOLO, Pandas, NumPy"],
    ["Data & Tools", "MySQL, MongoDB, Git, GitHub, Docker, Jupyter Notebook, Postman"],
    ["Responsible AI", "PII anonymisation, human-in-the-loop design, data minimisation (UK GDPR principles)"]
  ],
  projects: [
    { key: /job[\s-]?hunt|job (ads?|adverts?|listings?|search)|reed|remotive|vacanc|matching jobs/i,
      title: "AI Job Hunt Agent", tech: "n8n, Groq API, Reed & Remotive APIs, JavaScript, n8n Data Tables, AI Agent",
      bullets: [
        "Built a scheduled n8n agent that searches the Reed and Remotive job APIs every morning, fetches full adverts and filters out senior, old, irrelevant and duplicate roles.",
        "Used an LLM with strict JSON-schema output to rate each job requirement against the CV with exact quotes; JavaScript verifies every quote and calculates the match score, and flags paid training schemes and senior roles.",
        "Generated tailored CV summaries and cover letters for the top matches, with a safety check that removes any skill not found in the CV.",
        "Added a run log, error-alert workflow, dashboard and a chat agent with memory and four tools; moved search into a compact sub-workflow, cutting the agent's token use by about two-thirds."
      ] },
    { key: /cv|screen|candidate|recruit/i,
      title: "AI CV Screening Assistant", tech: "n8n, Groq API (gpt-oss-20b), JavaScript, Webhooks, REST APIs, n8n Data Tables, HTML/CSS, Docker",
      bullets: [
        "Built an n8n workflow that screens a CV against a job description and returns an evidence-based report, through an animated web form and a JSON webhook API.",
        "Moved scoring out of the LLM: the model rates each requirement and JavaScript calculates a 0-100 score from a weighted rubric (required 50%, preferred 20%, experience 20%, education 10%).",
        "Added a hallucination check that searches the CV for every AI evidence quote; unverified quotes get half credit and are flagged for the human reviewer.",
        "Anonymised personal details before the CV reaches the LLM; the same CV scored 82/100 in 3 repeated runs thanks to strict JSON-schema output, temperature 0 and a fixed seed."
      ] }
  ],
  education: [
    ["MSc Artificial Intelligence", "Teesside University, United Kingdom", "January 2026 – January 2028 (expected)", "Machine Learning, Deep Learning, Computer Vision, Natural Language Processing, Intelligent Systems and AI Applications."],
    ["B.Tech Computer Science and Engineering", "Christu Jyothi Institute of Technology and Science, Telangana, India", "October 2021 – July 2025", "Programming, Data Structures and Algorithms, Object-Oriented Programming, Database Management Systems and Software Engineering."]
  ],
  extra: ["Availability: [your availability]"]
};

let summary = ME.summary, topSkills = [], tailoredBullets = [], note = "";
if (!job) note = `No job found with id "${esc(q.job_id || "")}". Showing the general CV.`;
else if (!job.tailored_cv) note = "This job has no tailored version yet (only the top matches get one). Showing the general CV.";
else {
  const t = String(job.tailored_cv);
  const sec = (start, end) => { const m = t.match(new RegExp(start + "\\s*\\n([\\s\\S]*?)(?:\\n\\s*\\n|\\n" + end + "|$)")); return m ? m[1].trim() : ""; };
  const ts = sec("PROFESSIONAL SUMMARY \\(tailored\\)", "KEY SKILLS");
  // Clean CV style only: no "I / my / me" and no company name. Otherwise keep the polished base summary.
  const firstPerson = /\b(I|I'm|I've|my|me)\b/.test(ts);
  const namesCompany = job.company && ts.toLowerCase().includes(String(job.company).toLowerCase().split(/\s+/)[0]);
  if (ts && !firstPerson && !namesCompany) summary = ts;
  topSkills = sec("KEY SKILLS \\(put these first\\)", "PROJECT").split("·").map((s) => s.trim()).filter(Boolean);
  const b = t.match(/PROJECT BULLETS TO USE\s*\n([\s\S]*?)(?:\n\s*\n|\nATS|$)/);
  tailoredBullets = b ? b[1].split("\n").map((l) => l.replace(/^\s*-\s*/, "").trim()).filter(Boolean) : [];
}
const projects = ME.projects.map((p, idx) => {
  const mine = tailoredBullets.filter((x) => p.key.test(x) && !(idx === 1 && ME.projects[0].key.test(x)));
  return { ...p, bullets: mine.length >= 3 ? mine : p.bullets };
});
const target = job ? `${job.title} – ${job.company}` : "";
const row = (left, right) => `<table class="row"><tr><td class="l">${left}</td><td class="r">${right}</td></tr></table>`;
const body = `
<header><h1>${esc(ME.name)}</h1><p class="headline">${esc(ME.headline)}</p><p class="contact">${ME.contact.map(esc).join("&nbsp;&nbsp;|&nbsp;&nbsp;")}</p></header>
<h2>Profile</h2><p>${esc(summary)}</p>
<h2>Skills</h2>
${topSkills.length ? `<p class="core"><b>Core skills for this role:</b> ${topSkills.map(esc).join(" · ")}</p>` : ""}
<table class="skills">${ME.skills.map(([k, v]) => `<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join("")}</table>
<h2>Projects</h2>${projects.map((p) => `<div class="item">${row(`<b>${esc(p.title)}</b>`, "")}<p class="tech">${esc(p.tech)}</p><ul>${p.bullets.map((x) => `<li>${esc(x)}</li>`).join("")}</ul></div>`).join("")}
<h2>Education</h2>${ME.education.map(([d, s, w, r]) => `<div class="item">${row(`<b>${esc(d)}</b>`, esc(w))}<p class="tech">${esc(s)}</p><p class="small">Relevant areas: ${esc(r)}</p></div>`).join("")}
<h2>Additional Information</h2>${ME.extra.map((x) => `<p class="small">${esc(x)}</p>`).join("")}`;
const style = `body{font-family:Calibri,Arial,Helvetica,sans-serif;color:#1a1a1a;font-size:10.5pt;line-height:1.38;max-width:780px;margin:0 auto;padding:28px 32px;background:#fff}
header{text-align:center;margin-bottom:6px}
h1{font-size:22pt;margin:0;letter-spacing:.02em;color:#14284b}
.headline{margin:3px 0 2px;font-size:10.5pt;color:#3d4f6b;letter-spacing:.02em}
.contact{margin:2px 0 0;font-size:9.5pt;color:#333}
h2{font-size:10.5pt;text-transform:uppercase;letter-spacing:.12em;color:#14284b;border-bottom:1.2px solid #14284b;margin:14px 0 6px;padding-bottom:2px}
p{margin:3px 0}.small{font-size:10pt;color:#333}.core{margin:2px 0 6px}
.tech{margin:1px 0 0;color:#555;font-style:italic;font-size:9.5pt}
.item{margin:0 0 8px}
ul{margin:3px 0 0;padding-left:16px}li{margin:2px 0}
table.row{width:100%;border-collapse:collapse}table.row td{padding:0;vertical-align:bottom}td.r{text-align:right;white-space:nowrap;font-size:9.5pt;color:#444}
.skills{border-collapse:collapse;width:100%}.skills th{text-align:left;vertical-align:top;padding:2px 12px 2px 0;white-space:nowrap;font-size:10pt;width:1%;color:#14284b}.skills td{padding:2px 0;font-size:10pt}
.bar{font-family:Arial,sans-serif;background:#f3f6fa;border:1px solid #d5deea;border-radius:6px;padding:10px 12px;margin:0 auto 18px;max-width:780px;font-size:10pt}
@media print{.bar{display:none}body{padding:0}}`;

